using System;using System.Drawing;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace ServiceTool{
internal sealed class ServiceProbeForm:ManagerModuleForm{
readonly BrandTextBox address=new BrandTextBox();string swaggerAddress;readonly BrandButton swagger;string selectedAddress="";readonly string serviceName;readonly JournalTextBox journal=new JournalTextBox();readonly BrandButton check;readonly Label state;readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer();CancellationTokenSource cancellation;readonly CancellationTokenSource lifetime=new CancellationTokenSource();bool busy;
internal ServiceProbeForm(string name,bool preview=false):base("Проверка отклика службы",new Size(720,480)){
serviceName=name;HideThemeSelector();MinimumSize=SizeFromClientSize(new Size(720,480));ClientSize=new Size(720,480);Root.RowStyles[0].Height=64;FormBorderStyle=FormBorderStyle.FixedSingle;MaximizeBox=false;var body=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=7,Margin=Padding.Empty};body.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));foreach(float h in new[]{32F,32F,52F,32F,60F})body.RowStyles.Add(new RowStyle(SizeType.Absolute,h));body.RowStyles.Add(new RowStyle(SizeType.Percent,100));body.RowStyles.Add(new RowStyle(SizeType.Absolute,50));body.Controls.Add(ModuleHeading(System.IO.Path.IsPathRooted(name)?System.IO.Path.GetFileName(name):name),0,0);
body.Controls.Add(Label("Адрес подтверждается процессом службы или очередью HTTP.sys.\r\nМожно вручную указать локальный HTTP/HTTPS или TCP-адрес.",true),0,2);address.Dock=DockStyle.None;address.Anchor=AnchorStyles.Left|AnchorStyles.Right;address.AccessibleName="Диагностический адрес службы";address.Margin=new Padding(1,4,1,6);body.Controls.Add(address,0,3);state=Label("Проверка не настроена",true);state.AutoEllipsis=true;body.Controls.Add(state,0,4);body.Controls.Add(JournalPanel.Create(journal,"Журнал проверки отклика",Colors),0,5);
var actions=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=5,RowCount=1,Margin=new Padding(0,10,0,0)};for(int n=0;n<5;n++)actions.ColumnStyles.Add(new ColumnStyle(n%2==0?SizeType.Percent:SizeType.Absolute,n%2==0?100F/3:12));check=Button("Проверить отклик",true);check.Click+=async delegate{await Probe();};var monitor=new RefreshToggle{Text="Проверять каждые 10 с.",Size=new Size(290,30),Anchor=AnchorStyles.Top|AnchorStyles.Right,Palette=Colors,Margin=Padding.Empty};body.Controls.Add(monitor,0,1);body.Layout+=delegate{using(var graphics=monitor.CreateGraphics()){float scale=graphics.DpiX/96F;monitor.Width=1+(int)Math.Round(42*scale)+(int)(8*scale)+TextRenderer.MeasureText(graphics,monitor.Text,monitor.Font,Size.Empty,TextFormatFlags.NoPadding|TextFormatFlags.SingleLine).Width;monitor.Margin=new Padding(0,0,1,0);}};address.TextChanged+=delegate{if(!busy){check.Enabled=!String.IsNullOrWhiteSpace(address.Text);monitor.Enabled=check.Enabled;}};monitor.CheckedChanged+=delegate{timer.Enabled=monitor.Checked;};swagger=Button("Открыть Swagger",false);swagger.Enabled=false;swagger.Click+=delegate{if(String.IsNullOrEmpty(swaggerAddress))return;try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(swaggerAddress){UseShellExecute=true});}catch(Exception e){journal.AppendText("Не удалось открыть браузер: "+e.Message+Environment.NewLine);}};var close=Button("Назад",false);close.Click+=delegate{Close();};actions.Controls.Add(check,0,0);actions.Controls.Add(swagger,2,0);actions.Controls.Add(close,4,0);swagger.Margin=check.Margin=close.Margin=Padding.Empty;actions.SizeChanged+=delegate{int width=Math.Max(1,(actions.ClientSize.Width-actions.GetColumnWidths()[1]-actions.GetColumnWidths()[3])/3);foreach(int column in new[]{0,2}){actions.ColumnStyles[column].SizeType=SizeType.Absolute;actions.ColumnStyles[column].Width=width;}};Shown+=delegate{BeginInvoke((MethodInvoker)delegate{if(IsDisposed)return;int[] widths=actions.GetColumnWidths();int available=actions.ClientSize.Width-widths[1]-widths[3];int width=available/3;for(int c=0;c<5;c+=2){actions.ColumnStyles[c].SizeType=SizeType.Absolute;actions.ColumnStyles[c].Width=width;}actions.ColumnStyles[3].Width=widths[3]+available-width*3;});};body.Controls.Add(actions,0,6);monitor.Enabled=false;Root.Controls.Add(body,0,1);timer.Interval=10000;timer.Tick+=async delegate{await Probe();};FormClosing+=delegate{lifetime.Cancel();timer.Stop();if(cancellation!=null)cancellation.Cancel();};SetTheme(Colors.Dark,false);check.Enabled=false;if(!preview)Shown+=async delegate{try{state.Text="Определяем процесс и порты…";var info=await Task.Run(()=>System.IO.Path.IsPathRooted(serviceName)?ServiceEndpoints.InspectExecutable(serviceName):ServiceEndpoints.Inspect(serviceName));if(IsDisposed)return;state.Text=info.Summary;journal.AppendText(info.Summary+Environment.NewLine);swaggerAddress=await Task.Run(()=>ServiceSwagger.Find(info.HttpAddresses,lifetime.Token));if(IsDisposed)return;swagger.Enabled=!String.IsNullOrEmpty(swaggerAddress);journal.AppendText((swagger.Enabled?"Swagger обнаружен: "+swaggerAddress:"Swagger не обнаружен. Он может отсутствовать или быть отключён.")+Environment.NewLine);if(info.Checks.Count>0){selectedAddress=info.Checks[0];if(String.IsNullOrWhiteSpace(address.Text))address.Text=selectedAddress;check.Enabled=true;monitor.Enabled=true;await Probe();}else if(String.IsNullOrWhiteSpace(address.Text))state.Text=info.Summary+" Введи локальный адрес вручную.";}catch(Exception e){if(!IsDisposed)state.Text="Не удалось определить адрес: "+e.Message;}};
}
async Task Probe(){if(busy||IsDisposed||String.IsNullOrWhiteSpace(address.Text))return;busy=true;check.Enabled=false;address.ReadOnly=true;cancellation=new CancellationTokenSource();var token=cancellation.Token;try{string url=address.Text.Trim();bool automatic=String.Equals(url,selectedAddress,StringComparison.Ordinal);if(!automatic)journal.AppendText("Ручной адрес: "+url+". Принадлежность выбранной службе не подтверждена."+Environment.NewLine);var watch=System.Diagnostics.Stopwatch.StartNew();var result=await Task.Run(()=>{token.ThrowIfCancellationRequested();if(automatic&&!ServiceEndpoints.StillOwns(serviceName,url))return new ServiceProbeResult{Message="Адрес больше не подтверждён для выбранной службы. Закрой диагностику и открой заново."};return ServiceProbe.Check(url,token);});if(IsDisposed||token.IsCancellationRequested)return;state.Text=result.Message; journal.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+watch.ElapsedMilliseconds+" мс. "+result.Message+(result.Code==0?"":" HTTP "+result.Code)+Environment.NewLine);}catch(OperationCanceledException){}catch(Exception e){if(!IsDisposed){timer.Stop();state.Text=e.Message;}}finally{cancellation.Dispose();cancellation=null;busy=false;if(!IsDisposed){address.ReadOnly=false;check.Enabled=!String.IsNullOrWhiteSpace(address.Text);}}}
protected override void Dispose(bool disposing){if(disposing){lifetime.Cancel();timer.Dispose();if(cancellation!=null)cancellation.Cancel();}base.Dispose(disposing);}
}}
